window.__BUNDLE__={"generatedAt":"2026-09-06T15:46:41.349577+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-30","archiveCutoff":"2021-09-07","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":227,"arxiv":1305,"total":1532},"freshness":{"latestPaperDate":"2026-09-04","latestPublishedDate":"2026-09-04","latestBatchCount":242,"newInLast24h":0,"newInLast48h":0},"historyTotal":11566,"topicCounts":{"Multi-Agent":1882,"Evaluation":6066,"Planning":966,"Memory":256,"Code Agent":535,"Interpretability":405,"Agentic RAG":1036,"Agentic Search":1278,"RL for LLM":811,"Reasoning":3506,"Hallucination":693,"Post-Training":1515,"Alignment":1594,"World Model":142,"Tool Use":1072,"Agent Safety":2071,"Computer Use":220,"Reflection":467,"VLM Training":653,"LLM Training":1297,"Fine-tuning":1700,"Multimodal Agent":69,"Agent Framework":674,"Error Attribution":95,"Data Engine":245},"count":36,"recentTotal":1850,"archiveCount":0,"archiveTotal":9716,"sources":{"hf":61,"arxiv":1788,"semanticScholar":1},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"source":"hf","url":"https://arxiv.org/abs/2609.04148","hfUrl":"https://huggingface.co/papers/2609.04148","upvotes":271,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04148.pdf","id":"arxiv:2609.04148","authors":["Jie Wu","Zhenru Zhang","Beichen Zhang","Xuwu Wang","Yuhui Su","Mouxiang Chen","Peng Wang","Zhihai Wang","Que Shen","Hao Zhou","An Yang","Fei Huang","Yujiu Yang","Dayiheng Liu"],"title":"Terminal-Universe: Turning Agent Trajectories into Scalable Terminal Environments","announceDate":"2026-09-04","tags":["Post-Training","LLM Training","Code Agent","Fine-tuning"],"topics":["Post-Training","LLM Training","Code Agent","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.04148","submittedDate":"2026-09-03","abstract":"As terminal-based code agents become prevalent, agent trajectories have accumulated at scale, while realistic, executable environments remain scarce. However, environments are what agent post-training actually requires: each can be re-queried into many verifiable tasks and provides execution feedback, whereas a trajectory is a single frozen demonstration. Rather than generating environments from scratch, we observe that the tool-execution history in existing trajectories exposes the structure and contents of the environments in which they ran, making it possible to reconstruct those environments from the trajectories themselves. Thus, we introduce Terminal-Universe, a framework which turns each trajectory into a reusable environment and explores it for synthesizing new tasks and continued interactions. Specifically, Terminal-Universe replays the file operations recorded in a trajectory t"},{"source":"hf","url":"https://arxiv.org/abs/2609.03796","hfUrl":"https://huggingface.co/papers/2609.03796","upvotes":226,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03796.pdf","id":"arxiv:2609.03796","authors":["Chuyan Chen","Haoxing Chen","Kun Chen","Zhenglin Cheng","Long Cui","Ruishan Fang","Zhangxuan Gu","Zhicheng Huang","Zhenzhong Lan","Yuanting Lei","Haoquan Li","Jianguo Li","Rongchuan Li","Sidu Li","Tao Lin","Deyuan Liu","Jiacheng Liu","Lin Liu","Yuxuan Lou","Zhisheng Lu","Yuxin Ma","Shuheng Shen","Peng Sun","Chaoyang Wang","Hongjun Wang","Xiaomei Wang","Yongxin Wang","Chengzhang Wu","Hongru Wu","Jun Xie"],"title":"LLaDA-Image: Building Strong Image Generators with Fully Open Training Recipes","announceDate":"2026-09-04","tags":["LLM Training","VLM Training"],"topics":["LLM Training","VLM Training"],"arxiv":"https://arxiv.org/abs/2609.03796","submittedDate":"2026-09-03","abstract":"We introduce LLaDA-Image, a unified framework that pairs a 6B Diffusion Transformer (DiT) trained from scratch with a frozen vision-language understanding module built on the LLaDA2.0-Mini diffusion language model backbone. Instead of relying heavily on paired image-text data from the beginning, we first build a strong visual generative prior through image-only pre-training and mid-training. The generation pipeline comprises 220M samples, 98 of which are real images. For efficient and scalable optimization, we use parameter-free RMSNorm throughout the DiT together with the Muon optimizer. The resulting unified model produces highly photorealistic images while accurately following fine-grained editing instructions. We further distill LLaDA-Image into LLaDA-Image-Turbo, enabling fast inference in 2-4 sampling steps. On Qwen-Image-Bench, LLaDA-Image achieves overall scores of 53.53 and 53.3"},{"source":"hf","url":"https://arxiv.org/abs/2609.03430","hfUrl":"https://huggingface.co/papers/2609.03430","upvotes":161,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03430.pdf","id":"arxiv:2609.03430","authors":["Heng Wang","Jielin Qiu","Wenting Zhao","Cheng Qian","Liangwei Yang","Jiawei Han","Heng Ji","Silvio Savarese","Shelby Heinecke","Huan Wang"],"title":"Random Attention: Rethinking KV Cache Eviction for Efficient Reasoning","announceDate":"2026-09-04","tags":["Reasoning"],"topics":["Reasoning"],"arxiv":"https://arxiv.org/abs/2609.03430","submittedDate":"2026-09-03","abstract":"Large language models achieve superior performance on tasks that require extended reasoning, but long chains of thought make the KV cache a severe memory bottleneck. Existing KV cache compression methods share one paradigm: score each cached token by some estimate of how much it will matter later, and keep the top-scoring ones. We show that the selection signal contributes almost nothing. Random Attention keeps the prompt and evicts uniformly at random within each attention head, computing no score at all; across four models and six reasoning tasks it matches the strongest prior evictor while serving 32-43% higher throughput than it in vLLM deployment. Controlled experiments explain this by showing that 1) the prompt is the fragile part of the cache, and most of the gap between selectors is just whether their selection signal happened to keep it; 2) the reasoning trace protects itself ag"},{"source":"hf","url":"https://arxiv.org/abs/2609.04172","hfUrl":"https://huggingface.co/papers/2609.04172","upvotes":77,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04172.pdf","id":"arxiv:2609.04172","authors":["Zixuan Fu","Bingxiang He","Yuxin Zuo","Haohuan Huang","Jinqian Zhang","Ruhang Xiao","Cheng Qian","Qinyu Luo","Huan-ang Gao","Yudong Wang","Zhiyuan Liu","Ning Ding","Chaojun Xiao"],"title":"Rethinking On-Policy Distillation of Large Language Models II: One Training Example","announceDate":"2026-09-04","tags":["Post-Training","LLM Training","Alignment"],"topics":["Post-Training","LLM Training","Alignment"],"arxiv":"https://arxiv.org/abs/2609.04172","submittedDate":"2026-09-03","abstract":"On-policy distillation (OPD) combines student-generated rollouts with dense token-level supervision from a teacher. Existing work has mainly studied its algorithmic behavior, leaving the role of training data unclear. We examine this role at the data-minimal limit by training on a single query. One-shot OPD keeps improving for hundreds of steps and recovers most of full-data OPD's gain across task domains and model families. We explain this result through the states visited during training and the rate at which the student aligns with the teacher. We measure \\emph{state coverage}, the fraction of the states full-data OPD visits that a query set's rollouts reach. A single query already reaches \\(71.5\\%\\), most of it within the first 100 steps. Adding semantically distinct queries raises coverage and validation accuracy together, until 16 queries reach \\(98.9\\%\\) and match full-data traini"},{"source":"hf","url":"https://arxiv.org/abs/2609.04034","hfUrl":"https://huggingface.co/papers/2609.04034","upvotes":42,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04034.pdf","id":"arxiv:2609.04034","authors":["Junyan Ye","Wei Liu","Dongzhi Jiang","Zichen Wen","HaoDong Li","Zhutao Lv","Jiaxin Lin","Jinhua Yu","Jun He","Zilong Huang","Rui Chen","Weijia Li"],"title":"Editable Visual Design","announceDate":"2026-09-04","tags":["VLM Training","Reasoning","Planning","Code Agent"],"topics":["VLM Training","Reasoning","Planning","Code Agent"],"arxiv":"https://arxiv.org/abs/2609.04034","submittedDate":"2026-09-03","abstract":"While diffusion base models such as GPT-Image-2 and Nano-Banana exhibit remarkable visual expressiveness, their end-to-end generation inherently yields flattened bitmaps with error-prone text, precluding layer-wise post-editing. Conversely, code-based visual generation via Coding Agents provides precise layout control and decoupled layers, yet remains constrained by a lack of global aesthetic intuition and the difficulty of coding complex visual assets. To address this, we propose Editable Visual Design, a new paradigm driven by a Coding Agent. We designate the VLM as the ``creative brain'' for requirement comprehension, task planning, and aesthetic judgment, while utilizing the image generation model as an on-demand ``visual world simulator'' to synthesize standalone visual assets. Operating under an ``imagine first, then act'' closed-loop workflow, the agent generates isolated assets, "},{"source":"hf","url":"https://arxiv.org/abs/2609.04131","hfUrl":"https://huggingface.co/papers/2609.04131","upvotes":29,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04131.pdf","id":"arxiv:2609.04131","authors":["Hongyu Qu","Guangming Yao","Ling Xing","Xiaobin Hu","Rongxing Ding","Guibin Zhang","Fan Zhang","Yi Yuan","Xiangbo Shu","Shuicheng Yan"],"title":"Beyond Retrieval: Progressive Latent Memory Evolution for Streaming Video Understanding","announceDate":"2026-09-04","tags":["Reasoning","Memory","Evaluation"],"topics":["Reasoning","Memory","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.04131","submittedDate":"2026-09-03","abstract":"Streaming video understanding requires multimodal large language models (MLLMs) to process continuous visual inputs and respond to user queries under strict causality and bounded memory. Existing approaches typically compress historical observations into an external memory bank and retrieve query-relevant evidence as additional visual context. Though effective, this store-and-retrieve paradigm keeps historical evidence as external visual context, preventing it from being internalized into a compact, evolving latent memory that can continuously guide streaming reasoning. To bridge this gap, we introduce LatentStream, a progressive latent working memory framework that shifts streaming memory from store-and-retrieve to retrieve-and-internalize. Specifically, LatentStream comprises three coordinated components. First, Query-agnostic Hierarchical Streaming Memory organizes visual history into"},{"source":"hf","url":"https://arxiv.org/abs/2609.04083","hfUrl":"https://huggingface.co/papers/2609.04083","upvotes":24,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04083.pdf","id":"arxiv:2609.04083","authors":["Tingyu Song","Mingxin Li","Yanzhao Zhang","Dingkun Long","Chu Liu","Pengjun Xie","Yilun Zhao","Shu Wu"],"title":"CORE: Improving Compositional Reasoning in MLLM Embedding via Reranker Distillation","announceDate":"2026-09-04","tags":["Reasoning","Evaluation"],"topics":["Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.04083","submittedDate":"2026-09-03","abstract":"MLLM-based embedding models remain limited in compositional retrieval, often failing to distinguish scenes containing the same concepts but different attribute-object bindings. Yet the same backbone can resolve such distinctions when used as a cross-attentive reranker, motivating us to distill its compositional judgments into the embedding model. We propose CORE, which synthesizes candidate lists spanning five compositional matching levels and introduces a Rank-KL objective that trains the embedding model to reproduce the reranker's fine-grained ranking. We further introduce a graded evaluation protocol and compare contrastive learning, pairwise CoSENT, and listwise Rank-KL under the same data and tuning budget. Our comparison shows that both CoSENT and Rank-KL use the multi-level supervision more effectively than contrastive learning, with Rank-KL achieving the strongest overall perform"},{"source":"hf","url":"https://arxiv.org/abs/2609.03952","hfUrl":"https://huggingface.co/papers/2609.03952","upvotes":23,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03952.pdf","id":"arxiv:2609.03952","authors":["Yibin Wang","Zehan Wang","Junshu Tang","Zhimin Li","Yujie Zhou","Jiazi Bu","Pengyang Ling","Feng Han","Zhixiong Zhang","Long Xing","Shengyuan Ding","Ziang Li","Cheng Jin","Yuhang Zang","Jiaqi Wang","Tianyu Pang"],"title":"WorldReward: Reward Modeling for Camera-Conditioned World Models","announceDate":"2026-09-04","tags":["Post-Training","VLM Training","Reasoning","Evaluation","World Model"],"topics":["Post-Training","VLM Training","Reasoning","Evaluation","World Model"],"arxiv":"https://arxiv.org/abs/2609.03952","submittedDate":"2026-09-03","abstract":"Camera-conditioned world models generate interactive videos in which commanded actions should induce the expected scene changes while appearance, geometry, and temporal dynamics remain coherent. Existing rewards assess these requirements separately: geometry-based rewards estimate trajectory execution but cannot judge the visual quality of the executed motion, whereas image-based rewards measure frame quality without capturing action execution or temporal dynamics. We posit that a vision-language model (VLM) offers a shared reasoning space for relating actions to their visual outcomes. However, judging a complete long video against its full action sequence creates a lengthy, noisy context in which short-lived local action evidence can be missed or diluted. We present WorldReward, a VLM-based pairwise preference reward model that unifies action-consistency and visual-quality evaluation fo"},{"source":"hf","url":"https://arxiv.org/abs/2609.03563","hfUrl":"https://huggingface.co/papers/2609.03563","upvotes":19,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03563.pdf","id":"arxiv:2609.03563","authors":["Byeongjun Park","Byung-Hoon Kim","Hyungjin Chung"],"title":"FlashRender: Few-Step Generative Rendering via Camera-Controlled Video MeanFlow","announceDate":"2026-09-04","tags":["Alignment","Fine-tuning"],"topics":["Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03563","submittedDate":"2026-09-03","abstract":"We present FlashRender, a few-step generative rendering framework that retakes a source video along a target camera trajectory in seconds. We identify sampling-step-dependent camera control as a prominent manifestation of discretization error in existing multi-step generative rendering models and show that resolving this inconsistency substantially lowers denoising trajectory curvature, facilitating subsequent step distillation. To this end, we introduce Representation Transformation and Alignment (RETA), which aligns hidden source-video representations with target-video features from a frozen visual geometry model. This directly encodes the geometric transformation within the source-video stream, enabling sampling-step-consistent camera control. We then fine-tune the model with the MeanFlow objective on the lower-curvature denoising trajectory induced by RETA, allowing the model to more"},{"source":"hf","url":"https://arxiv.org/abs/2609.04128","hfUrl":"https://huggingface.co/papers/2609.04128","upvotes":17,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04128.pdf","id":"arxiv:2609.04128","authors":["Zhiyuan Fan","Tinghao Yu","Yuanjun Cai","Jiang Zhou","Jiangtao Guan","Jincheng Liu","Yun Yang","Dingxin Hu","Zhuo Han","Xing Wu","Feng Zhang","Lilin Wang"],"title":"Environment Evolution for Terminal Agents","announceDate":"2026-09-04","tags":["Multi-Agent"],"topics":["Multi-Agent"],"arxiv":"https://arxiv.org/abs/2609.04128","submittedDate":"2026-09-03","abstract":"Scaling interactive and verifiable environments is critical for training terminal agents. As frontier models become more capable, environments synthesized from scratch become less challenging and thus provide limited learning signals. Recent co-evolution methods iteratively synthesize environments near the model's learnable frontier based on weaknesses exposed during rollouts. However, their dependence on on-policy rollouts limits generalization and the continuous provision of learning signals as the model becomes stronger. In this paper, we propose environment evolution, which incrementally increases environment difficulty off-policy and schedules the evolved environments generation by generation during training to provide continuous learning signals. We derive three evolution directions that influence environment difficulty from the multi-turn learning objective and then implement evol"},{"source":"hf","url":"https://arxiv.org/abs/2609.04200","hfUrl":"https://huggingface.co/papers/2609.04200","upvotes":16,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04200.pdf","id":"arxiv:2609.04200","authors":["Varun Varma Thozhiyoor","Shivam Tripathi","Venkatesh Babu Radhakrishnan","Anand Bhattad"],"title":"Principia: Relational Physics Tests for Video Models","announceDate":"2026-09-04","tags":["VLM Training","Reasoning","Evaluation"],"topics":["VLM Training","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.04200","submittedDate":"2026-09-03","abstract":"Evaluating physical reasoning in video models is difficult because absolute motion measurements depend on frame rate, object scale, and camera calibration, all of which are often ambiguous or unavailable in generated video. We propose a different approach. When two objects in the same scene obey the same physical law, their motions must satisfy predictable relationships, and these relationships hold independent of calibration. We introduce Principia, a benchmark that evaluates Newtonian physics through relational consistency between paired objects. Principia spans eight phenomena - gravity, restitution, friction, rotational inertia, projectile motion, momentum, pendulum, and mass-spring oscillation - across translational, rotational, collisional, and oscillatory dynamics, using real-world scenes recorded under controlled protocols. We also introduce a calibration-independent consistency "},{"source":"hf","url":"https://arxiv.org/abs/2609.01865","hfUrl":"https://huggingface.co/papers/2609.01865","upvotes":6,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.01865.pdf","id":"arxiv:2609.01865","authors":["Aaryan Kapoor","Md Abdullah Al Hafiz Khan"],"title":"ExecRetrieval: Measuring the Functional-Correctness Gap in Code-Embedding Retrieval","announceDate":"2026-09-04","tags":["Agentic Search","Code Agent","Evaluation"],"topics":["Agentic Search","Code Agent","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.01865","submittedDate":"2026-09-01","abstract":"Embedding-based code retrieval is a core component of coding agents and retrieval-augmented code generation, where retrieving correct code matters more than retrieving lexically similar code. Existing code-retrieval benchmarks do not plant controlled, execution-verified single-edit variants of each query's canonical implementation in the search pool, leaving the question of whether embeddings can functionally discriminate correct from near-clone-but-incorrect code unanswered in a retrieval setting. Resolving this requires a benchmark whose search pool itself contains the relevant counterfactuals -- execution-verified buggy variants near-identical to each canonical -- so that a retriever's rank ordering can be directly tested for functional discrimination rather than topical or identity overlap. We introduce ExecRetrieval, 939 Python tasks each paired with one execution-verified canonical"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04173","hfUrl":"https://huggingface.co/papers/2609.04173","upvotes":27,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04173.pdf","id":"arxiv:2609.04173","authors":["Vilém Zouhar","Niyati Bafna","Mukund Choudhary","Maike Züfle","Sara Rajaee","Pinzhen Chen","Jannis Vamvas","Sara Papi","Ona de Gibert","Bhavitvya Malik","Eliya Habba","Orfeas Menis Mastromichalakis","Patrícia Schmidtová","Michelle Wastl","Sheriff Issaka","Leshem Choshen","Stella Biderman","Antonis Anastasopoulos","Jan Niehues","Rico Sennrich","Mrinmaya Sachan","Ondřej Bojar","Kenton Murray","Jörg Tiedemann","Alham Fikri Aji","Philipp Koehn","Christof Monz","Alexandra Birch","Sowmya Vajjala","Chalamalasetti Kranti","Cristina España-Bonet","Nobin Sarwar","David Kaczér","Shunta Asano","Malik Marmonier","Daban Q. Jaff","Vaisakhi Mishra","Hend Al- Khalifa","Gabriele Sarti","Sourajit Saha","Nils Rehlinger","Juan Daniel Cuervo Villa","Jonathan Tonglet","Saugata Purkayastha","Dominik Macháček","Jagannathan Ramanujam","Heejin Do","Zuzana Nadova","Fred Philippy","Fabian Retkowski","Maria Lymperaiou","Silvia Casola","Hanna Yukhymenko","Shubhashis Roy Dipta","Sangwon Ryu","Andrés Jerez","Ron Keinan","Shuaib Shuaib Yusuf","Avantica Vempati","Maria Carmen Staiano","Sukannya Purkayastha","Adrian Cosma","Vitalii Babenko","Erivan Inan","Aviral Nigam","Wafa Aissa","Fatima Haouari","Venkata Prasanth Kumar Gummadi","Mehdi Jafarzadeh","Valentin Scourneau","Lukas Edman","Kaiser Sun","Shaomu Tan","Mohammad Sadegh Gholizadeh","Johannes-Rudolf David","Dipankar Srirag","Javier García Gilabert","Ruta Binkyte","Manar Ali","Ana-Maria Bucur","Sabry E. Farrag","Youssef Saber","Yihong Liu","Jean Maillard","Cojocaru Nicoleta","Xiaochuang Yuan","Sina Ahmadi","Philipp Mondorf","Kaustubh Dhole","Roman Wixinger","Shenbin Qian","Manuel Tuor","Sergey Troshin","Jonathan Yahav","Fida Mohammad Thoker","Amir Arsalan Rezapour","Lance Calvin Lim Gamboa","Manon Reusens","Kätriin Kukk","Koel Dutta Chowdhury","Giuseppe Gallipoli","Christian Hoang","Shaswati Saha","Seth Aycock","Jan Kocoń","Bo Chen","Linh Vu","Vatsal Venkatkrishna","Arafat Ahsan","Luan Thanh Nguyen","Hassan Soliman","Daryna Dementieva","Theresia Veronika Rampisela","Ngoc Quynh Tram Do","Marius Huber","Kazuki Egashira","Azmine Toushik Wasi","Vladislav Poritski","Mike Zhang","Deep Shah","Paul Gavrikov","Luis Frentzen Salim","David Africa","R. Damanhuri","Bello Umar Bello","Anumit Garg","Gengyu Rao","Pawan Sasanka Ammanamanchi","Kamile Dementaviciute","Andrianos Michail","L D M S Sai Teja","Dawei Zhu","Yi Fan","Wei Liu","Farhan Farsi","Elias Herranen","Sankalan Pal Chowdhury","Karen Sanchez","Farzad Shami","Ashok Urlana","Zimu Wang","Tomasz Limisiewicz","Priyaranjan Pattnayak","Marii Ojastu","Hongbin Na","Emilian Radoi","Chenyi Zhao","Carlos Hinojosa","Andrea Gregor de Varda","Zaid Alyafeai","Reem Alzahrani","Nehal Kathrotia","Alex Flückiger","Ulysses Sekai Tully Carr","Jimson Paulo Layacan","Guy Kaplan","Ritwik Tiwari","Rishit Dagli","Oksana Volchek","Isaac R Caswell","Bowen Yi","Blanka Kövér","Amir Hossein Yari","Aicha Chorana","Zhengxiang Wang","Selja Keränen","Samuel Simko","Joy Olusanya","Jenny Chim","Enzo Doyen","Vivek Harsha Lakkamaneni","Sophia Conrad","Pouya Sadeghi","Panayiotis Panayiotou","Luis Lara","Jannatul Nayem","Eran Yahav","Debanshu Das","Antonia Karamolegkou","Anmol Goel","Aishik Mandal","Tommaso Cerruti","Raoyuan Zhao","Mykola Haltiuk","Thura Aung","Naser Almousa","Amir Hossein Kargaran","Rachel Bawden","Qiaoyuan Zheng","Mateusz Lango","Beni Egressy","Fidel Rodríguez Velásquez","Natchapon Jongwiriyanurak","Minh Ngoc Do","Marco Gaido","Lena Libon","Dzmitry Kuzmin","Badal Nyalang","Antoine Taroni","Andrei Niculae","Abdulaziz Nura Kani","Rushikesh Zawar","Marek Šuppa","Beatrice Savoldi","Andreas Simons","Rayyan Merchant","Ilai Yaron Levy","Francesco Pinto","Ziyi Yang","Yolanda Xavier","Samuel Frontull","Muhammad Ravi Shulthan Habibi","Kenneth Enevoldsen","Harris Abdul Majid","Francesca Padovani","Tim Graf","Tatiana Bielakova","Sharifa Djurabaeva","Shaoxiong Ji","Raia Abu Ahmad","Pavel Stepachev","Jirui Qi","Ayush Sunil Munot","Alireza Pakniat","Ayla Rigouts Terryn","Yuxing Lu","Yurii Paniv","Xiyan Fu","Tosin Adewumi","Sunisth Kumar","Stéphane J. P. S. Thunus","Shree Harsha Bokkahalli Satish","Shayan Bali","Prakhar Gupta","Papa Abdou Karim Karou Diallo","Matija Akrap","Marko Culjak","Kristýna Onderková","Joseph Attieh","Esrael Teferi Tensay","Elisabeth Fittschen","Benoît Sagot","Jingwei Ni","Yu Fan"],"title":"Last Translation Benchmark","announceDate":"2026-09-04","tags":["Evaluation"],"topics":["Evaluation"],"arxiv":"https://arxiv.org/abs/2609.04173","submittedDate":"2026-09-03","abstract":"For scientific progress, we need benchmarks that test the limits of state-of-the-art models, and evaluation methods that inform us about failure cases. As models get stronger, standard benchmarks for machine translation are approaching saturation. Further, automatic translation metrics are unreliable, vulnerable to reward-hacking, and provide unactionable assessments. Even gold human evaluation is not problem-free, because it often lacks reproducibility, objectivity, and scalability. Overall, this prevents us from tracking objective progress in the field and identifying pathways for improvement. We introduce the Last Translation Benchmark, a collection of human-authored and peer-reviewed examples (texts, images, audio, videos) that break leading machine translation models. We also present a new evaluation approach: each example comes with handcrafted verification rules describing concret"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04094","hfUrl":"https://huggingface.co/papers/2609.04094","upvotes":23,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04094.pdf","id":"arxiv:2609.04094","authors":["Shubham Gandhi","Saurabh Goyal","Kiran Kate","Yara Rizk"],"title":"DRACO: Fine-Grained Credit Assignment with Dynamic Rubrics for Long-Horizon Agent Training","announceDate":"2026-09-04","tags":["Post-Training"],"topics":["Post-Training"],"arxiv":"https://arxiv.org/abs/2609.04094","submittedDate":"2026-09-03","abstract":"Reinforcement Learning from Verifiable Rewards works well when a task has a programmatic checker, but most long-horizon agent domains have none. We work in the outcome-blind setting, where ground-truth success signals are not available. Multi-criteria rubrics are a popular way to supply such a reward; they are scored once per trajectory, but a single scalar is a poor signal across tens of steps. We propose DRACO: Distributing Rubric-based Advantage for Credit Optimization. It generates rubrics dynamically during training to track the policy's evolving capability, scores those rubrics once per completed trajectory, and redistributes that judgment over the steps responsible for annotated rubrics to produce differentiated per-step advantages in GRPO. The redistribution is closed-form and does not introduce any trained attribution module. On AppWorld, DRACO gains 15.9 points over the base mo"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03293","hfUrl":"https://huggingface.co/papers/2609.03293","upvotes":22,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03293.pdf","id":"arxiv:2609.03293","authors":["Yoojin Kim","Jihyoung Jang","Hyounghun Kim"],"title":"PACE: Towards Surfacing Hidden Conflicts in User Requests","announceDate":"2026-09-04","tags":["Multi-Agent","Evaluation","Agent Framework"],"topics":["Multi-Agent","Evaluation","Agent Framework"],"arxiv":"https://arxiv.org/abs/2609.03293","submittedDate":"2026-09-03","abstract":"Personalized assistants should not only comply with user requests but also assess whether those requests are appropriate given the user's current circumstances. However, prior work has primarily focused on accurately executing requests, overlooking the need for assistants to account for context and engage in conflict-based refusal. Furthermore, while existing work on conflict or safety detection relies on explicitly provided factors, real-world scenarios often involve implicit factors that must be retrieved from a knowledge base (KB). To this end, we introduce Personalized Assistants for Conflict Evaluation (PACE), a dataset for evaluating whether models can identify latent constraints, expressed as egocentric knowledge or events, that render seemingly reasonable user requests inappropriate. PACE pairs user requests grounded in well-defined personas with egocentric KB facts, requiring mo"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03153","hfUrl":"https://huggingface.co/papers/2609.03153","upvotes":12,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03153.pdf","id":"arxiv:2609.03153","authors":["Wenzhuo Xu","Yuchen Zhu","Chongjian Ge","Xuan Shen","Jing Shi","Jason Kuen","Yongxin Chen","Molei Tao","Christopher McComb","Noelia Grande Gutiérrez","Jiuxiang Gu"],"title":"VeriPhy: Agentic Physical Reasoning for World Model Evaluation and Refinement","announceDate":"2026-09-04","tags":["Reasoning","World Model"],"topics":["Reasoning","World Model"],"arxiv":"https://arxiv.org/abs/2609.03153","submittedDate":"2026-09-02","abstract":"Visual fluency in generated video does not imply physical reliability, and a scalar quality score alone is incapable of indicating the obligation a clip violates or the moment it fails. We present VeriPhy, an auditable physical-verification system in which a text-only planner compiles the prompt into typed physical obligations and a statically validated execution plan before any frame is observed. During execution, observations gate and scope only declared calls to frozen low-level experts (e.g., segmentation and tracking, counting, eleven typed physical measurements over the resulting tracks, depth, OCR, and audio-event detection). Each action returns a provenance-carrying evidence record whose payload, when usable, is either a typed measurement or an explicitly tagged learned state. Typed resolvers and fixed composition map usable records to a three-valued state (supported, contradicte"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04063","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04063.pdf","id":"arxiv:2609.04063","authors":["Jiamian Wang","Samyadeep Basu","Koustava Goswami","Tong Yu","Zhiqiang Tao"],"title":"Spurious Advantage Hidden in GRPO","announceDate":"2026-09-04","tags":["Agentic Search","Post-Training","Reasoning","Evaluation","RL for LLM"],"topics":["Agentic Search","Post-Training","Reasoning","Evaluation","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.04063","submittedDate":"2026-09-03","abstract":"Group Relative Policy Optimization (GRPO) is widely studied for reinforcement learning with verifiable rewards, where its advantage estimator assigns each rollout a magnitude from within-group reward statistics. In the common case, this magnitude rewards rollouts that reach the correct answer through reasoning. Yet, an overlooked case shares the same surface: a rollout may land on it by guessing, and the formula still assigns a high magnitude, which we identify as the spurious advantage. This arises in three cases: bounded-answer tasks with a small candidate set; open-answer sets hosting bounded sub-cases; and search agents whose budget opens many paths to the same answer. In all three, this misleads the policy toward guess-like behaviors. We propose SIGNBALANCE, whose magnitude is composition-free: it keeps the verifier sign, uses a global scale, and restores zero-mean balance via a sto"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04061","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04061.pdf","id":"arxiv:2609.04061","authors":["Tongyao Zhu","Wei Hern Lim","Min-Yen Kan"],"title":"When Models Edit Too Much: On the Fidelity of Minimal Code Edits","announceDate":"2026-09-04","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.04061","submittedDate":"2026-09-03","abstract":"Large language models (LLMs) are increasingly used to edit existing code, but correctness alone is not enough: useful repairs should also be minimal, reviewable, and faithful to the original implementation. We study over-editing, the tendency of a model to rewrite code beyond what is required to fix a bug. We construct an evaluation framework from 400 BigCodeBench problems by injecting controlled AST-level corruptions into reference solutions, giving each repair task a known minimal patch. Across frontier LLMs, over-editing is widespread even among strong models like GPT-5.5: high Pass@1 can coexist with unnecessarily large edits and added cognitive complexity. A preservation instruction substantially reduces this behavior, lowering average excess Levenshtein distance from 0.195 to 0.131, reducing added cognitive complexity by 26.6%, and increasing Pass@1 by 2.3 points. However, these ga"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03806","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03806.pdf","id":"arxiv:2609.03806","authors":["Marco Cipriano","Leonardo Zini","Alexandra Schild","Valentin Teutschbein","Afsana Mimi","Marcella Cornia","Lorenzo Baraldi","Gerard de Melo"],"title":"SVG-Score: Human-Aligned Evaluation of Text-to-SVG Generation","announceDate":"2026-09-04","tags":["LLM Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"topics":["LLM Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03806","submittedDate":"2026-09-03","abstract":"Scalable Vector Graphics (SVG) generation is attracting increasing attention as generative models improve in expressiveness and controllability. Progress, however, is held back by the lack of domain-specific evaluation protocols: current practice relies on metrics designed for natural images, most notably CLIPScore, which was never trained on vector graphics and aligns only partially with human judgment. We introduce \\textbf{\\ours}, a human-aligned evaluation framework for text-to-SVG generation. Through controlled caption and image perturbations, we first show that CLIP-based scores barely react to the errors SVG generators actually make, such as wrong colors, counts, and spatial relations, and that off-the-shelf Vision-Language Model (VLM) judges, while more sensitive, respond unevenly across error types and SVG styles. We then introduce a human-annotated dataset for \\textit{Semantic A"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04108","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04108.pdf","id":"arxiv:2609.04108","authors":["Boyan Li","Bingsen Chen","Chenghao Yang","Ping Nie","Chen Zhao","Xi Ye"],"title":"Sequential Beats Joint: On the Interplay between On-Policy Distillation and RLVR","announceDate":"2026-09-04","tags":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"topics":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.04108","submittedDate":"2026-09-03","abstract":"Reinforcement learning with verifiable rewards (RLVR) and on-policy distillation (OPD) have emerged as two dominant methods for post-training reasoning LLMs. Prior work uses OPD's dense token-level supervision to complement the sparse RL reward, fusing the two signals within a single step: either as a \\emph{weighted-additive combination} or a \\emph{teacher-modulated rescaling} of the RL advantage. In this paper, we show that a simple two-stage scheme, OPD-then-RL, consistently outperforms pure OPD, pure RLVR, and all such joint baselines across logic and math reasoning benchmarks. Beyond the empirical results, we further provide a systematic understanding of this through pass@$k$ behavior, learning dynamics, and parameter updates, yielding a consistent explanation: OPD expands the student's coverage of teacher-supported solutions and RL sharpens within that support, while jointly optimiz"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03414","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03414.pdf","id":"arxiv:2609.03414","authors":["Chenglin Wu","Junjie Wu","Jinhang Chen","Mingyang Chen","Zixu Lin","Jiabian Chen","Xinghao Ding","Xiaotong Tu"],"title":"StrixAE: An Intelligent Agent for Audio Enhancement under Complex Distortion Coupling in Real-World Scenarios","announceDate":"2026-09-04","tags":["Agent Safety","LLM Training","Reasoning","Hallucination","Fine-tuning"],"topics":["Agent Safety","LLM Training","Reasoning","Hallucination","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03414","submittedDate":"2026-09-03","abstract":"Audio enhancement in real-world scenarios involves complex distortion couplings and requires personalized enhancement. Existing solutions struggle to address both simultaneously. To improve robustness and enable autonomous operation in such scenarios, we propose StrixAE, an agent based on a multimodal large language model (MLLM). StrixAE leverages the MLLM as a controller to coordinate multiple audio enhancement and personalization models. To further enhance system robustness, reduce artifacts, and improve generalization across diverse real-world scenarios, StrixAE is trained through a two-stage process: first, CoT supervised fine-tuning on AcoustBench to ground basic reasoning and tool invocation; second, Audio Perception Reinforcement Learning (APRL), a reward design specifically tailored for audio restoration pipelines that jointly optimizes format validity, structural coherence, and "},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03887","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03887.pdf","id":"arxiv:2609.03887","authors":["Hoang Cuong Nguyen","Mark Dras","Usman Naseem"],"title":"Beyond Shallow Alignment: How Post-Training Methods Determine Refusal Circuits And Steering Robustness","announceDate":"2026-09-04","tags":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"topics":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03887","submittedDate":"2026-09-03","abstract":"How do the methods used to train language models to refuse harmful requests shape how that refusal actually works inside the model? We compare three post-training methods - supervised fine-tuning, reasoning-augmented fine-tuning (training on reasoning chains that justify a safety decision), and preference optimization (ORPO) - across three architecturally distinct models (Llama-3.1-8B, Gemma-2-9B, Qwen3-8B). We find that training method, not just data, reshapes how refusal is computed internally: reasoning-augmented training consistently produces a distinct kind of refusal computation, visible across all three models, while architecture independently shapes internal structure and how reliably refusal can be steered. Most importantly, no method we study achieves all three properties we would want from safe alignment at once: refusal that isn't concentrated in a few fragile components, saf"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04194","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04194.pdf","id":"arxiv:2609.04194","authors":["Kevin Du","Alexander Hoyle","Laura Ruis","Acyr Locatelli"],"title":"Legibility is Not Interpretability: Comparing Judged and Actual Importance in Chain-Of-Thought Reasoning","announceDate":"2026-09-04","tags":["Post-Training","Reasoning","Hallucination","Interpretability","Fine-tuning"],"topics":["Post-Training","Reasoning","Hallucination","Interpretability","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.04194","submittedDate":"2026-09-03","abstract":"Reasoning traces from chain-of-thought models appear to offer a legible window into how a model arrives at its answer. A growing body of work treats them as such, using LLM judges to diagnose errors, evaluate faithfulness, and provide step-level supervision via process reward models and generative critics. These practices rely on the text of a reasoning step carrying information about its functional role. But does the text actually encode information about which reasoning steps matter? We operationalize the importance of a reasoning step as its advantage: the change in expected reward, e.g., producing the correct final answer, from including that step, estimated via Monte Carlo rollouts. Basing ground truth on these estimates, we evaluate whether LLM judges can identify high-advantage steps and find that sufficiently capable LLMs can outperform a prevalence baseline but fall well short o"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03338","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03338.pdf","id":"arxiv:2609.03338","authors":["Leqi Zheng","Jinbo Su","Yuying Li","Chaokun Wang","Weiping Wang","Haitao Li","Jiajun Zhang","Shannan Yan","Zhaolu Kang","Rong Fu","Jie Wu","Fang Niu","Hang Zhang"],"title":"SciLENS: RL-Driven Autonomous Agents for Scientific Localized Evidence Navigation and Synthesis","announceDate":"2026-09-04","tags":["Reasoning","Planning","Evaluation","Data Engine","Agent Framework"],"topics":["Reasoning","Planning","Evaluation","Data Engine","Agent Framework"],"arxiv":"https://arxiv.org/abs/2609.03338","submittedDate":"2026-09-03","abstract":"Scientific literature synthesis agents increasingly rely on proprietary online services, limiting reproducibility, privacy, and offline deployment. To address this challenge, we introduce SciLENS Scientific Localized Evidence Navigation and Synthesis), a fully local autonomous agent framework operating on a dual-tier infrastructure indexing approximately 12 million academic records. SciLENS pioneers the integration of structural visualization as an actionable tool within the reasoning loop, enabling the agent to compress complex citation topologies into validated data-driven charts and thereby mitigate context exhaustion during macro-level synthesis. To train the agent without human annotation, we develop an automated data synthesis pipeline that extracts multi-hop subgraphs from a citation knowledge graph, verified by cross-model consensus among 20 frontier models. The agent is subseque"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03674","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03674.pdf","id":"arxiv:2609.03674","authors":["Xiangchen Pan","Jiayi Xu","Jing Wang","Xing Fang","Lingyun Zhu"],"title":"LLM4AIGQ: LLM-based AI Guidance Query Generation Framework for Multi Interest Mining","announceDate":"2026-09-04","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.03674","submittedDate":"2026-09-03","abstract":"Guidance queries stimulate user consumption by extracting preferences to provide search queries with guidance value, playing a crucial role in the e-commerce field. Traditional AI-generated queries (AIGQ) generation primarily relies on a two-stage \"Query-to-AI-Generated-Query\" (Q2AIGQ) association paradigm, first recalling user primary search queries from user profiles, historical behavior sequences, item-side information, and the current query through multi-path retrieval, then generalizing AIGQ via rule-based methods. This approach suffers from semantic drift due to information cascade loss; additionally, primary search query derivation heavily depends on \"user-item\" co-occurrence relationships, lacking exploration of user multi-interests, resulting in guidance queries with low value and mismatched purchase intent. To address the expressive limitations of traditional co-occurrence-base"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03342","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03342.pdf","id":"arxiv:2609.03342","authors":["Leqi Zheng","Jinbo Su","Fang Niu","Chaokun Wang","Weiping Wang","Jiajun Zhang","Shannan Yan","Jie Wu","Zhaolu Kang","Rong Fu","Hang Zhang"],"title":"Gradients Know What Outcomes Don't: Unlocking Reinforcement Learning for LLM Reasoning with Gradient-Aligned Rewards","announceDate":"2026-09-04","tags":["Post-Training","Reasoning","Evaluation","Alignment","RL for LLM"],"topics":["Post-Training","Reasoning","Evaluation","Alignment","RL for LLM"],"arxiv":"https://arxiv.org/abs/2609.03342","submittedDate":"2026-09-03","abstract":"Reinforcement learning from verifiable rewards (RLVR) drives chain-of-thought reasoning in large language models, yet its binary outcome reward cannot distinguish among correct trajectories. Existing dense reward alternatives, from surface heuristics to process reward models, either ignore the expert solutions already present in training corpora or require expensive offline annotation. We propose Gradient-Aligned Reward (GAR), which operates in the policy's own gradient space: truncated backpropagation through the output projection layer extracts a compact gradient vector for each rollout, and cosine similarity with an expert-anchor gradient yields a dense, reasoning-aware reward with less than 9% wall-clock overhead. We prove that this cosine admits a multiplicative decomposition into prediction-error and activation-pattern factors, providing a concrete characterization of what the alig"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03544","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03544.pdf","id":"arxiv:2609.03544","authors":["Caoyuan Ma","Tian Gu","Wenpu Liu","Weichu Xie","Shuai Dong","Yuqi Xu","Ji Zhao","Ziyue Wang","Wenzheng Chang","Taiqiang Wu","Yongfu Zhu","Wenqi Shao","Zheng Wang","Yinqiang Zheng"],"title":"SafeRI: Recognition and Intervention for Token-Level Safety Intervention in Large Vision Language Models","announceDate":"2026-09-04","tags":["VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"topics":["VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03544","submittedDate":"2026-09-03","abstract":"Existing safety alignment methods for vision-language models usually modify the model behavior globally: once the safety parameters are trained or loaded, they participate in both unsafe and already-safe generations. This always-on intervention can unnecessarily perturb the model's original reasoning path and degrade general multimodal capabilities. We argue that safety alignment should be an on-demand intervention rather than a permanent modification to every decoding trajectory. To this end, we propose a streaming recognition and gated LoRA framework for intrinsic VLM safety. During autoregressive generation, a lightweight recognizer estimates whether the current pre-token generation state is safe or unsafe. Its output updates the LoRA gate for the following decoding step; otherwise, generation follows the frozen-backbone policy. The LoRA module is trained from unsafe prefixes, transit"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03553","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03553.pdf","id":"arxiv:2609.03553","authors":["Linh Le","Melanie Bui","My Chiffon Nguyen","Zachary Schlosser","David Williams-King"],"title":"GPS-Bench: A Governance Policy Benchmark for Automating Policy Analysis","announceDate":"2026-09-04","tags":["Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"topics":["Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03553","submittedDate":"2026-09-03","abstract":"Policy analysis requires more than predicting whether a proposal will pass: it requires identifying who will be affected, how those actors respond, and what follows. LLM-based policy simulations model these processes at scale, but their validity is hard to establish when plausible behaviour is never compared with observed outcomes. We introduce GPS-Bench, an evidence-grounded benchmark for governance policy simulation that links policies to relevant actors, actor actions and downstream impacts using legislative records, lobbying disclosures, regulatory documents, corporate filings, economic data and other public evidence. Actors are reconstructed from the dated record rather than prompted as archetypes, so a persona is an evidence object with provenance; a human-annotated pool forms the Gold evaluation set, while cases labelled by a separate LLM from retrieved evidence are treated as Sil"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.04048","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.04048.pdf","id":"arxiv:2609.04048","authors":["Hasan Alkhder","Mohammad Abboush","Igor Tchappi","Ahmet Zengin","Amro Najjar"],"title":"Translation as a Decision Space: A Multi-Agent Perspective on Low-Resource Dialect Generation","announceDate":"2026-09-04","tags":["Multi-Agent","Evaluation","Interpretability","Fine-tuning"],"topics":["Multi-Agent","Evaluation","Interpretability","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.04048","submittedDate":"2026-09-03","abstract":"Neural machine translation (NMT) systems typically produce a single output per input, obscuring the alternative decision trajectories implicitly available within multilingual decoding. This opacity becomes particularly problematic in low-resource dialect settings, where multiple linguistically valid realizations may differ in lexical authenticity, register, and structural stability. We propose reframing translation as a structured decision space explored by autonomous translation agents. Instead of analyzing a single output, we model distinct translation pathways as agents operating over a shared multilingual backbone. Inter-agent divergence is treated not as error but as an interpretable behavioral signal. We conduct an empirical study on Turkish--Syrian Arabic translation using three agents: (1) zero-shot direct translation, (2) dialect-stabilized translation via lightweight fine-tunin"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03874","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03874.pdf","id":"arxiv:2609.03874","authors":["Vineet Kumar","Meghanadh Pulivarthi","vishwajeet kumar","Jaydeep Sen","Riyaz Ahmad Bhat","Sachindra Joshi"],"title":"STAIR (STructure Aware Information Retriever): A novel dataset and LLM based retriever for document structure augmentation","announceDate":"2026-09-04","tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.03874","submittedDate":"2026-09-03","abstract":"Retrieval Augmented Generation (RAG) is a key component for generating accurate and hallucination free answers using Large Language Models (LLMs). LLMs are improving at handling long context, but still suffer from \"lost in the middle\" problem. Thus, precise and accurate retrieval is important. Current retrievers chunk long context into length-based manageable chunks - in the process throwing away rich and informative semantic global structure in the corpus. We introduce a novel retrieval system STAIR that empowers an LLM to exploit global structure in a corpus such as a Table of Contents (ToC) to efficiently store and retrieve information from its model parameters. Our thorough and careful ablation studies with a finetuned Differentiable Search Index (DSI) system show that ToC helps build a low hallucination (less than 0.05%) generative Information Retrieval (IR) system and can generaliz"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03493","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03493.pdf","id":"arxiv:2609.03493","authors":["Xingming Long","Yu Liu","Zhiwei Yang","Hanqi Feng","Shaojie Zhang","Barnabas Poczos","Chao Jiang","Zhenbo Luo","Lei Jiang","Pei Fu"],"title":"Making Every Tool Call Count: Necessary Tool-Evidence Path Rewards for Agentic Vision-Language Models","announceDate":"2026-09-04","tags":["VLM Training","Tool Use","Reasoning","Evaluation"],"topics":["VLM Training","Tool Use","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.03493","submittedDate":"2026-09-03","abstract":"Modern vision-language models (VLMs) can directly answer many image-grounded questions, yet they often struggle with complex queries requiring fine-grained visual details or external knowledge. To acquire this missing evidence, agentic VLMs invoke tools such as image cropping, image search, and text search. However, existing training paradigms primarily evaluate tool-use based on final answer correctness, leaving evidence acquisition and utilization insufficiently supervised. This leads to two critical shortcomings: (i) models frequently issue redundant or off-target tool calls that fail to gather necessary evidence, and (ii) even when appropriate tools are called, models often fail to extract the necessary information from the resulting observations. To address these limitations, we introduce the NTEP (Necessary Tool-Evidence Path), a novel annotation scheme that explicitly specifies th"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03941","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03941.pdf","id":"arxiv:2609.03941","authors":["Hyun Bin Park","Du-Seong Chang"],"title":"Headroom-Drift Replay: A Primitive for Principled Replay Control in GRPO","announceDate":"2026-09-04","tags":["Agentic Search","Post-Training","Reasoning","Evaluation"],"topics":["Agentic Search","Post-Training","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.03941","submittedDate":"2026-09-03","abstract":"RL-based post-training for reasoning models is increasingly bottlenecked by repeated fresh rollout generation, particularly in agentic settings where environment interaction dominates wall-clock cost. Replay can reduce this burden by reusing past trajectories, but existing methods typically embed it within larger training pipelines involving exploration, experience restructuring, or mixed-policy optimization. This makes replay's own contribution difficult to isolate. We ask a focused question: how far can principled replay selection alone go? We introduce Headroom-Drift Replay, a group-level replay control primitive for GRPO that separates reuse into two decisions. Headroom ranks stored groups by remaining learning value, while Drift gates them by compatibility with the current policy. The fresh on-policy stream remains unchanged, and the method adds no auxiliary generation or training m"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03880","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03880.pdf","id":"arxiv:2609.03880","authors":["Xiaomi-TabLDM Team",":","Penghui Wang","Wei Liu","Hong Wang","Chengyue Huang","Yuxi Sun","Zirui Wang","Hongming Huang","Quan Wang","Chunxiao Liu","Erli Meng","Bin Wang"],"title":"Xiaomi-TabLDM: A Tabular Foundation Model Technical Report","announceDate":"2026-09-04","tags":["LLM Training","Evaluation","Fine-tuning","Data Engine"],"topics":["LLM Training","Evaluation","Fine-tuning","Data Engine"],"arxiv":"https://arxiv.org/abs/2609.03880","submittedDate":"2026-09-03","abstract":"We introduce Xiaomi-TabLDM, a tabular large data foundation model for classification and regression via in-context learning, which delivers superior prediction accuracy without requiring task-specific fine-tuning. Pretrained exclusively on synthetic data generated from structural causal models (SCMs), our model enables more flexible context utilization and more efficient capacity scaling. i) A new performance standard. Strong regression performance across benchmarks: Xiaomi-TabLDM ranks 1st on OpenML-CTR23 and 2nd on regression across TALENT, TabArena, and BCCO, demonstrating consistently strong regression performance across four complementary benchmark suites. Favorable performance--efficiency trade-off: Xiaomi-TabLDM combines strong predictive performance with substantially lower computational cost. For example, on TabArena regression, it achieves the second-highest Elo while using 82%"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03611","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03611.pdf","id":"arxiv:2609.03611","authors":["Zaruhi Navasardyan","Tatul Danielyan","Hrant Davtyan"],"title":"FailBench: How Reliable are VLMs at Judging Robot Task Success?","announceDate":"2026-09-04","tags":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"topics":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2609.03611","submittedDate":"2026-09-03","abstract":"Vision-Language Models (VLMs) are increasingly used to evaluate robot manipulation outcomes, but existing benchmarks offer limited evidence of cross-domain generalization. We introduce FailBench, a benchmark for robot failure detection comprising 2,197 manipulation attempts across 14 public sources (12 real-world, 2 simulated). In FailBench, 75% of failures occur naturally, and six real-world sources come from non-failure-detection datasets. Evaluating 13 VLM-based detectors, we find the best model achieves only 0.77 mean balanced accuracy. Notably, models fine-tuned for failure detection consistently underperform general-purpose VLMs and their own pretrained baselines. Performance depends heavily on required visual evidence: models approach saturation when outcomes depend on observable object motion, but degrade to near-chance (<0.60 balanced accuracy) on contact-intensive assembly task"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.03756","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.03756.pdf","id":"arxiv:2609.03756","authors":["Javier del Pino","Salvador Rodríguez","Alejandro Garabito","Javier Álvarez","Chema Garabito"],"title":"ENEAS: Embedding-guided Neural Ensemble for Adaptive Segmentation","announceDate":"2026-09-04","tags":["VLM Training","Reasoning","Hallucination","Reflection"],"topics":["VLM Training","Reasoning","Hallucination","Reflection"],"arxiv":"https://arxiv.org/abs/2609.03756","submittedDate":"2026-09-03","abstract":"We present ENEAS, a unified, text-promptable method for instance tracking and semantic discovery. Text-promptable segmentation models, including the latest foundation models such as SAM 3, still suffer from temporal hallucinations, spatial fragmentation, and semantic misclassification: they fail to report target absence when an object leaves the field of view, segment local textures instead of the complete object during extreme close-ups, and prioritize visual features over ontological reality, so that visually similar artifacts such as statues, paintings, or reflections are segmented as target entities. ENEAS works two ways from a single method: precise tracking and high-quality segmentation of a unique instance, and open-concept discovery of every instance a text query names, resolved by a semantic verification layer. For tracking, we extend the geometrically robust SeC architecture, p"},{"source":"arxiv","url":"https://arxiv.org/abs/2609.02954","upvotes":0,"date":"2026-09-04","pdf":"https://arxiv.org/pdf/2609.02954.pdf","id":"arxiv:2609.02954","authors":["Huiyuan Xie","Yuqin Huang","Zhicheng Hao","Yida Cai","Shaochun Wang","Zhenghao Liu","Yuxiao Ye"],"title":"LexIssue: Benchmarking Legal Issue Identification in Chinese Civil Litigation","announceDate":"2026-09-04","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2609.02954","submittedDate":"2026-09-02","abstract":"Identifying the issues disputed between litigating parties is a crucial component of real-world litigation. However, legal issues remain comparatively underexplored in legal AI research. In this work, we study the computational modelling of legal issue identification in litigation. We introduce a legally grounded hierarchical schema that represents legal issues through both free-form issue descriptions and structured legal categories, and formulate legal issue identification as two complementary tasks: legal issue generation and legal issue classification. Based on this formulation, we construct LexIssue, a benchmark containing 430 real-world Chinese civil litigation cases and 1,303 expert-annotated disputed legal issues. We further develop an issue-centric legal knowledge base spanning 27 causes of action and 441 candidate legal issue entries to support retrieval-augmented reasoning. Ex"}],"archive":[],"latestPath":"data/latest.json"};
